-- Mutants inside a feature area only need that area's test files (keeps the run time down); everything else runs the full list.
local BASE_FILTERS = "test_units test_roles test_spells.lua test_tooltip test_profiles test_errors test_aura_combat test_util_ui test_bars_ui test_strict_macros test_icon_tips test_shipping test_secure_wrap test_pins test_range test_aura_spacing test_secret_guards test_options_window test_meta_labels test_minimap_button test_secret_lifecycle"
local AURA_TESTS = "test_aura_perrow test_aura_container test_aura_stale test_aura_cache test_aura_combat test_icon_tips test_tooltip test_debug_log test_aura_spacing test_bars_ui test_secret_lifecycle"
local BUFF_TESTS = "test_role_inherit test_buff_groups test_buff_buttons_groups test_buff_pane test_buff_migration test_rebuff test_roles test_units test_buffbutton test_strict_macros test_ui_features test_shipping test_profiles test_secret_lifecycle test_secret_guards"
local RAID_TESTS = "test_raid_layout test_raid_frames test_raid_clickcast test_raid_settings test_raid_visuals test_raid_buffs test_raid_debuffs test_party_golden test_raid_switching"
local ROUTES = {
    ["Util/RaidLayout.lua"] = RAID_TESTS, ["Frames/RaidFrames.lua"] = RAID_TESTS, ["Frames/RaidStyle.lua"] = RAID_TESTS,
    ["Frames/Auras.lua"] = AURA_TESTS, ["Frames/Auras.xml"] = AURA_TESTS .. " test_toc", ["HealerForever.toc"] = AURA_TESTS .. " test_toc",
    ["Buffs/Presets.lua"] = BUFF_TESTS, ["Buffs/BuffButtons.lua"] = BUFF_TESTS, ["Options/BuffPresetsPane.lua"] = BUFF_TESTS, ["Data/Classes.lua"] = BUFF_TESTS,
    -- files shared by many features run everything
    ["Core.lua"] = FILTERS, ["Options/Window.lua"] = FILTERS, ["Options/Panes.lua"] = FILTERS, ["Options/Slash.lua"] = FILTERS,
    ["Options/CopyWindow.lua"] = "test_debug_log test_options_window test_secret_guards test_shipping test_report",
    ["Options/Perf.lua"] = "test_perf test_report test_commands",
    ["Options/Report.lua"] = "test_report test_commands test_options_window test_ui_features", ["Options/ContactPane.lua"] = "test_report test_commands test_options_window test_ui_features",
}
local function failSet(out)
    local set = {}
    for line in out:gmatch("[^\n]+") do
        local name = line:match("^  FAIL  (.+)$")
        if name then set[name] = true end
    end
    return set
end
local baselineFails
local function baseline()
    if not baselineFails then
        local out = sh('HF_MUTANT=1 luajit "' .. HF_TESTS .. '/run.lua" ' .. FILTERS .. '; echo EXIT=$?')
        baselineFails = failSet(out)
    end
    return baselineFails
end

describe("mutation sanity", function()
    if not L.exists(L.tocPath) then it("addon present", function() error("addon missing") end) return end
    local tmp = os.getenv("TMPDIR") or "/tmp"
    local base = (tmp:gsub("/$", "")) .. "/hf_mutant_" .. tostring(os.time())
    for i, m in ipairs(MUTATIONS) do
        it("mutant #" .. i .. " (" .. m.name .. ") is caught by the unit tests", function()
            local src = L.path(m.file)
            if not L.exists(src) then return skip(m.name, "file missing") end
            local content = L.readFile(src)
            local a, b = content:find(m.pattern, 1, true)
            if not a then
                if m.optional then return end
                error("mutation pattern '" .. m.pattern .. "' not found in " .. m.file .. " (update test_mutation.lua)")
            end
            local dir = base .. "_" .. i
            sh('rm -rf "' .. dir .. '" && mkdir -p "' .. dir .. '" && cp -R "' .. L.addonDir .. '" "' .. dir .. '/HealerForever"')
            local mutated = content:sub(1, a - 1) .. m.replace .. content:sub(b + 1)
            local f = assert(io.open(dir .. "/HealerForever/" .. m.file, "wb")); f:write(mutated); f:close()
            local out = sh('HF_MUTANT=1 HF_ADDON_DIR="' .. dir .. '/HealerForever" luajit "' .. HF_TESTS .. '/run.lua" ' .. (m.tests or ROUTES[m.file] or BASE_FILTERS) .. '; echo EXIT=$?')
            sh('rm -rf "' .. dir .. '"')
            local mutantFails, base = failSet(out), baseline()
            local new = false
            for name in pairs(mutantFails) do if not base[name] then new = true end end
            assertTrue(new, "mutant SURVIVED (no test fails that did not already fail) - tests are hollow for: " .. m.name)
        end)
    end
end)
